#!/usr/bin/env python3
"""Builds docs/LEMO-STYLE-INDEX.md and assets/lemo-styles/INDEX.json from the vendored Lemo-Opuscar styles (assets/lemo-styles/styles/*/{style.json,STYLE.md}).
Edit the CURATION dict below (our pipeline-fit tags and 'best for' picks), then run:  python3 scripts/build_lemo_index.py"""
import json, glob, os, re
R = os.path.dirname(os.path.dirname(os.path.abspath(__file__))); D = R + '/assets/lemo-styles'
# fit: '3d' = natural in our three.js engine; '2d' = DOM/canvas/shader page; 'real' = needs real imagery/data/CAD/footage (ask or skip); flags: chars = relies on human-like characters (banned by our rules unless the cast is non-human/voxel); culture = cultural/mythological material (check our banned list, treat with care)
CURATION = {
 '3d': 'memphis-diorama tilt-shift lowpoly-island brick-toy paper-popup glass-product hd-2d printed-long-take desktop-flythrough white-model data-physical teardown circuit-board transit-map isometric-picture-book iso-infographic hologram-hud paper-lantern shadow-puppet'.split(),
 'real': 'archive-lighttable lidar-survey microscope satellite-briefing white-model teardown kino-montage newsreel visual-investigation city-symphony living-screencast'.split(),
 'chars': 'rubber-hose cel-anime-80s scifi-toon midcentury-toon crayon-book pixel-rpg hd-2d paper-popup microgame silent-film shadow-puppet game-show'.split(),
 'culture': 'papercut-red ukiyoe ink-wash paper-lantern shadow-puppet stained-glass'.split(),
}
rows = []
for f in sorted(glob.glob(D + '/styles/*/style.json')):
    j = json.load(open(f)); slug = j['slug']; st = open(os.path.dirname(f) + '/STYLE.md').read()
    m = re.search(r'^> (.+)$', st, re.M); ess = (m.group(1) if m else '').strip()
    ess = re.sub(r'\s+', ' ', ess)[:260]
    fit = '3D' if slug in CURATION['3d'] else '2D'
    rows.append(dict(slug=slug, name=j['en'], category=j['category_en'], uses=j.get('uses', []), demo_film=j.get('film', ''), demo_sec=j.get('dur'), essence=ess, pipeline=fit, needs_real_assets=slug in CURATION['real'], human_like_characters=slug in CURATION['chars'], cultural_material=slug in CURATION['culture'], path=f'assets/lemo-styles/styles/{slug}/STYLE.md'))
json.dump(rows, open(D + '/INDEX.json', 'w'), indent=1, ensure_ascii=False)
byc = {}
for r in rows: byc.setdefault(r['category'], []).append(r)
def flag(r): return ''.join([' 🎬real-assets' if r['needs_real_assets'] else '', ' 🧍characters' if r['human_like_characters'] else '', ' 🏮culture' if r['cultural_material'] else ''])
out = ['<!-- generated by scripts/build_lemo_index.py from assets/lemo-styles/styles/*/style.json; edit the CURATION dict or the GUIDE text in that script, then re-run -->']
out.append(open(R + '/scripts/lemo_guide.md').read())
out.append('\n## 4. Full catalogue (66 styles, by category)\nFlags: **3D** = natural fit for our three.js engine, **2D** = DOM/canvas/shader page; 🎬 needs real imagery/data/CAD/footage (ask the creator or choose another); 🧍 relies on human-like characters (banned by our rules unless the cast is non-human, voxel or objects); 🏮 cultural/mythological material (check the banned list in `docs/STYLE-ROAST-EXPLAINER.md`, never for roast jokes).\n')
for c, rs in byc.items():
    out.append(f'\n### {c}\n\n| Style (folder) | Best for | Essence | Fit |\n|---|---|---|---|')
    for r in rs: out.append(f"| **{r['name']}** (`{r['slug']}`) | {', '.join(r['uses'])} | {r['essence'].replace('|','/')} | {r['pipeline']}{flag(r)} |")
open(R + '/docs/LEMO-STYLE-INDEX.md', 'w').write('\n'.join(out) + '\n'); print(len(rows), 'styles indexed')
